"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["35693"],{82024(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_categorico","status":422,"titulo":"S\xf3 fato categ\xf3rico tem valores de dom\xednio pr\xf3prios"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_categorico","requisitos":["UNI-REQ-0065","UNI-REQ-0159"],"oQueAconteceu":["S\xf3 o fato cujo tipo de dado \xe9 categ\xf3rico, isto \xe9, escolhido numa lista de op\xe7\xf5es, tem valores de dom\xednio (UNI-REQ-0065). O fato indicado em `{id}` \xe9 de outro tipo de dado, como booleano, n\xfamero, texto, data ou endere\xe7o, e por isso n\xe3o aceita valores. A recusa vale para o acr\xe9scimo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`), para a corre\xe7\xe3o (`PUT .../valores/{codigo}`) e para a reordena\xe7\xe3o (`PUT .../ordem-dos-valores`).","A confer\xeancia do fato vem antes de qualquer confer\xeancia do corpo e, na corre\xe7\xe3o, antes da busca do valor: a recusa \xe9 esta mesmo que o `{codigo}` n\xe3o exista. A busca do fato vem primeiro: com um `{id}` que n\xe3o existe, a resposta \xe9 a de fato n\xe3o encontrado (`uniplus.configuracao.fato_candidato.nao_encontrado`). O fato de sistema \xe9 recusado antes, com `uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada`. O fato que resume respostas de grupo cujo tipo de dado \xe9 categ\xf3rico passa por esta confer\xeancia e \xe9 recusado logo em seguida, com `uniplus.configuracao.fato_candidato.agregado_nao_tem_valores_proprios`, porque os valores do resumo de grupo s\xe3o os do fato de membro e s\xe3o mantidos nele; o resumo de grupo de outro tipo de dado, como o booleano, recebe esta recusa. Nada \xe9 gravado."],"comoResolver":["Envie a opera\xe7\xe3o para um fato categ\xf3rico do administrador. Se as op\xe7\xf5es s\xe3o mesmo necess\xe1rias, altere o tipo de dado do fato para categ\xf3rico (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`, regra do UNI-REQ-0159) antes de cadastrar os valores. Se a altera\xe7\xe3o for recusada pela defini\xe7\xe3o, cadastre um fato novo com o tipo de dado desejado."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo","Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);